mapper.select:
SELECT s.*, st.student_no, st.name as student_name, COALESCE(ca_cl.class_name, st_cl.class_name) as class_name, as derived_status, c.course_name, t.name as teacher_name, ca.semester FROM score s LEFT JOIN student st ON s.student_id = st.id LEFT JOIN course_arrangement ca ON s.course_arrangement_id = ca.id LEFT JOIN class ca_cl ON ca.class_id = ca_cl.id LEFT JOIN class st_cl ON st.class_id = st_cl.id LEFT JOIN course c ON ca.course_id = c.id LEFT JOIN teacher t ON ca.teacher_id = t.id
AND s.student_id = #{studentId}
AND ca.teacher_id = #{teacherId}
AND s.course_arrangement_id = #{courseArrangementId}
AND ca.semester = #{semester}
ORDER BY s.create_time DESC
